so a web LF. Confirmación individual o masiva por Excel o selección múltiple y Confirmar. Recordatorio editable inicial {param:PAYMENTS.PARTNER_VOUCHER_FIRST_REMINDER_HOURS}, posteriores {param:PAYMENTS.PARTNER_VOUCHER_REPEAT_REMINDER_HOURS} hasta respuesta. Cuota en validación sin vencimiento ni otro pago; confirmación genera comprobante, rechazo devuelve pendiente con aviso/motivo. Binding runtime pendiente; no modifica IG, fuentes oficiales ni legadas.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/234","solicitante":"Cristhian / Claude S22-AV"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"av_partner_payment_notification"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"av_automatic_payment_waits_partner"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"av_automatic_notice_not_email"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"av_automatic_notice_not_after_confirmation"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"av_automatic_notice_payload_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"av_automatic_notice_retry_or_timeout"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"av_automatic_notice_provider_named"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"av_voucher_partner_not_enabled"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"av_voucher_ocr_or_completion_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"av_voucher_request_payload_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"av_voucher_web_confirmation_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"av_voucher_bulk_confirmation_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho"