BEGIN
 IF lf_ops.nucleo_param_valor_v1('PAYMENTS.PARTNER_VOUCHER_FIRST_REMINDER_HOURS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='PAYMENTS' AND config_key='PARTNER_VOUCHER_FIRST_REMINDER_HOURS' AND hecho='av_voucher_first_reminder') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT PAYMENTS.PARTNER_VOUCHER_FIRST_REMINDER_HOURS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('PAYMENTS.PARTNER_VOUCHER_REPEAT_REMINDER_HOURS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='PAYMENTS' AND config_key='PARTNER_VOUCHER_REPEAT_REMINDER_HOURS' AND hecho='av_voucher_repeat_reminder') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT PAYMENTS.PARTNER_VOUCHER_REPEAT_REMINDER_HOURS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('NOTIFICATIONS.DAILY_USER_LIMIT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='NOTIFICATIONS' AND config_key='DAILY_USER_LIMIT' AND hecho='av_notif_daily_limit') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT NOTIFICATIONS.DAILY_USER_LIMIT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('NOTIFICATIONS.NON_OPERATIONAL_START_HOUR') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='NOTIFICATIONS' AND config_key='NON_OPERATIONAL_START_HOUR' AND hecho='av_notif_start_hour') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT NOTIFICATIONS.NON_OPERATIONAL_START_HOUR'; END IF;
 IF lf_ops.nucleo_param_valor_v1('NOTIFICATIONS.NON_OPERATIONAL_END_HOUR') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='NOTIFICATIONS' AND config_key='NON_OPERATIONAL_END_HOUR' AND hecho='av_notif_end_hour') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT NOTIFICATIONS.NON_OPERATIONAL_END_HOUR'; END IF;
 IF lf_ops.nucleo_param_valor_v1('NOTIFICATIONS.OFFER_EXPIRY_ALERT_HOURS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='NOTIFICATIONS' AND config_key='OFFER_EXPIRY_ALERT_HOURS' AND hecho='av_notif_expiry_hours') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT NOTIFICATIONS.OFFER_EXPIRY_ALERT_HOURS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('NOTIFICATIONS.DUE_REMINDER_EARLY_DAYS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='NOTIFICATIONS' AND config_key='DUE_REMINDER_EARLY_DAYS' AND hecho='av_notif_early_days') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT NOTIFICATIONS.DUE_REMINDER_EARLY_DAYS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('NOTIFICATIONS.DUE_REMINDER_LATE_DAYS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='NOTIFICATIONS' AND config_key='DUE_REMINDER_LATE_DAYS' AND hecho='av_notif_late_days') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT NOTIFICATIONS.DUE_REMINDER_LATE_DAYS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('TECH.SUBMIT_STEP1_TIMEOUT_MS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='TECH' AND config_key='SUBMIT_STEP1_TIMEOUT_MS' AND hecho='av_submit_timeout') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT TECH.SUBMIT_STEP1_TIMEOUT_MS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('TECH.OTP_SEND_TIMEOUT_MS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='TECH' AND config_key='OTP_SEND_TIMEOUT_MS' AND hecho='av_otp_timeout') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT TECH.OTP_SEND_TIMEOUT_MS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('TECH.LOAD_STEP3_TIMEOUT_MS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='TECH' AND config_key='LOAD_STEP3_TIMEOUT_MS' AND hecho='av_step3_timeout') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT TECH.LOAD_STEP3_TIMEOUT_MS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('TECH.CHECKOUT_TIMEOUT_MS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='TECH' AND config_key='CHECKOUT_TIMEOUT_MS' AND hecho='av_checkout_timeout') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT TECH.CHECKOUT_TIMEOUT_MS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('TECH.SCREEN_LOAD_RETRY_LIMIT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='TECH' AND config_key='SCREEN_LOAD_RETRY_LIMIT' AND hecho='av_screen_retries') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT TECH.SCREEN_LOAD_RETRY_LIMIT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('TECH.DNI_CROSS_RETRY_LIMIT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='TECH' AND config_key='DNI_CROSS_RETRY_LIMIT' AND hecho='av_dni_retries') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT TECH.DNI_CROSS_RETRY_LIMIT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('TECH.DNI_CROSS_BACKOFF_FIRST_MS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='TECH' AND config_key='DNI_CROSS_BACKOFF_FIRST_MS' AND hecho='av_dni_backoff_first') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT TECH.DNI_CROSS_BACKOFF_FIRST_MS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('TECH.DNI_CROSS_BACKOFF_SECOND_MS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='TECH' AND config_key='DNI_CROSS_BACKOFF_SECOND_MS' AND hecho='av_dni_backoff_second') THEN RAISE EXCEPTION 'S22AV_PARAM_PREFLIGHT TECH.DNI_CROSS_BACKOFF_SECOND_MS'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22AV_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 h:=lf_ops.nucleo_hash_paquete_v1(cd,1); hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22AV_VECTOR_FAIL %',cd; END IF;
 END LOOP;
 END LOOP;
 SELECT string_agg(j.key||'='||j.value,',' ORDER BY j.key) INTO hash_all FROM jsonb_each_text(hashes) j;
 RAISE EXCEPTION 'S22AV_HASH_ALL %',hash_all;
END $av$;
COMMIT;
